package com.accenture.taskmanager.service;

import com.accenture.taskmanager.model.Task;
import java.util.List;
import java.util.Optional;

/**
 * Interfaz del servicio de gestión de tareas.
 * Define las operaciones de negocio desacopladas de la infraestructura web.
 */
public interface TaskService {
    /** Obtiene el listado completo de tareas */
    List<Task> findAll();

    /** Busca una tarea por su identificador */
    Optional<Task> findById(Long id);

    /** Crea una nueva tarea y genera su ID */
    Task create(Task task);

    /** Actualiza los datos de una tarea existente */
