### 3. Implementación: `TaskServiceImpl.java`

```java
package com.accenture.taskmanager.service.impl;

import com.accenture.taskmanager.model.Task;
import com.accenture.taskmanager.service.TaskService;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Implementación en memoria del servicio de tareas.
 * Centraliza la lógica de negocio (SRP).
 */
@Service
public class TaskServiceImpl implements TaskService {

    // — generado por IA
    private final List<Task> tasks = new ArrayList<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    @Override
    public List<Task> findAll() {
        return new ArrayList<>(tasks);
    }

    @Override
    public Optional<Task> findById(Long id) {
        return tasks.stream().filter(t -> t.getId().equals(id)).findFirst();
    }

    @Override
    public Task create(Task task) {
        task.setId(idGenerator.getAndIncrement());
        tasks.add(task);
        return task;
    }

    @Override
    public Optional<Task> update(Long id, Task updatedTask) {
        return findById(id).map(existing -> {
            existing.setTitle(updatedTask.getTitle());
            existing.setDescription(updatedTask.getDescription());
            existing.setCompleted(updatedTask.isCompleted());
            return existing;
        });
    }

    @Override
    public boolean delete(Long id) {
        return tasks.removeIf(t -> t.getId().equals(id));
    }
}
```

